import type { ExampleRun } from "../types";
import flask from "../examples/pallets__flask.json";
import httpie from "../examples/httpie__cli.json";
import click from "../examples/pallets__click.json";

/** Plans generated by the real agent and saved as JSON, so the demo works even when Gemini doesn't. */
export const EXAMPLES: { slug: string; blurb: string; run: ExampleRun }[] = [
  { slug: "pallets/flask", blurb: "The Python micro web framework. Contributing guide lives off-repo, which the agent flags.", run: flask as ExampleRun },
  { slug: "httpie/cli", blurb: "A friendly command-line HTTP client. Makefile-driven setup and clear PR rules.", run: httpie as ExampleRun },
  { slug: "pallets/click", blurb: "Python's go-to library for building CLIs. Lots of open, unlabeled issues to rank.", run: click as ExampleRun },
];

export function findExample(fullName: string) {
  return EXAMPLES.find((e) => e.slug.toLowerCase() === fullName.toLowerCase());
}
